/* =====================================================================
   BASIC COURSE — part 2 (lessons b15–b30)
   ===================================================================== */
const wDesk=(inner,o={})=>desk(inner,Object.assign({app:'Word',menus:['File','Edit','View','Insert','Format','Tools','Help'],run:['finder','word']},o));
const pDesk=(inner,o={})=>desk(inner,Object.assign({app:'PowerPoint',menus:['File','Edit','View','Insert','Format','Arrange','Slide Show'],run:['finder','ppt']},o));
const xDesk=(inner,o={})=>desk(inner,Object.assign({app:'Excel',menus:['File','Edit','View','Insert','Format','Tools','Data'],run:['finder','excel']},o));
const toEdge=(k)=>['fn',async p=>{const r=p.rel(p.q(k));p.cx=r.l;p.cy=r.t+r.h/2;p.setCur();await sleep(850)}];
const selCells=(cells,ms=160)=>['fn',async p=>{for(const c of cells){p.q('c-'+c)?.classList.add('rng');await sleep(ms)}}];
const clearRng=['fn',async p=>{$$('.rng',p.m).forEach(e=>e.classList.remove('rng'))}];
const wordFileMenu=()=>menu('fmenu',[['fm-new','{{New Blank Document||New}}','{{⌘N||}}'],['fm-open','Open…','{{⌘O||}}'],'-',['fm-save','Save','{{⌘S||}}'],['fm-saveas','Save As…','{{⇧⌘S||F12}}'],'-',['fm-print','Print…','{{⌘P||}}']],7.5,3.4,true,'m-file');
const pptTabsOn=(t)=>['fn',async p=>{PTABS.forEach(x=>p.q('t-'+slug(x))?.classList.toggle('on',x===t))}];
const fruitData={A1:'Fruit',B1:'Votes',A2:'Mango',B2:6,A3:'Banana',B3:4,A4:'Apple',B4:5,A5:'Strawberry',B5:8};
const prevDock=['finder','launch','safari','mail','preview','word','ppt','excel','settings','|','trash'];

/* ============================== UNIT 3: Word & PowerPoint ============================== */
L({id:'b15',t:'Word: your first document',goal:'Open Microsoft Word, type, change the font and save your work.',warm:'typing',warmLevel:3,
learn:[
 {h:'Open Word',p:`<p>Click the blue <b>W</b> {{in the Dock||on the taskbar or in the Start menu}} (or {{use Spotlight: <kbd>⌘</kbd> + <kbd>space</kbd>||press <kbd>⊞ Windows</kbd>}}, type <b>word</b>, press <kbd>return</kbd>).</p><p>Click <b>Blank document</b>. A clean white page appears, ready for you!</p>`,
  demo:DEMO(()=>desk(win('wg','Microsoft Word',`<div style="padding:2cqw 2.4cqw;display:flex;flex-direction:column;gap:1.4cqw;flex:1;background:#fafafa"><b style="font-size:1.8cqw">New</b><div style="display:flex;gap:2cqw"><div style="text-align:center;font-size:1.2cqw"><div data-k="blank" style="width:13cqw;aspect-ratio:.77;background:#fff;box-shadow:0 0 0 1px #ccc;border-radius:.3cqw"></div>Blank document</div><div style="text-align:center;font-size:1.2cqw;opacity:.6"><div style="width:13cqw;aspect-ratio:.77;background:#fff repeating-linear-gradient(#fff 0 1.6cqw,#dde 1.6cqw 1.8cqw);box-shadow:0 0 0 1px #ccc;border-radius:.3cqw"></div>Newsletter</div></div></div>`,[16,6,62,70],'off')+wordWin('',{cls:'off'}),{run:['finder']}),[['cap','Click the blue W.',300],['to','d-word'],['click'],['cls','d-word','bounce'],['cls','d-word','run'],['show','wg',600],['cls','d-word','bounce',false],['cap','Click <b>Blank document</b>.',300],['to','blank'],['click'],['cls','blank','hl',true,400],['hide','wg'],['show','word',700],['cap','Your empty page is ready!']],{start:[50,50]})},
 {h:'Start typing',p:`<p>The <b>blinking line</b> shows where your words will go. Just start typing!</p><p>Press <kbd>return</kbd> to start a new paragraph. Word wraps long lines by itself, so only press <kbd>return</kbd> when you want a new paragraph.</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p data-k="t1"></p><p data-k="t2"></p>`)),[['cap','Type a title…',300],['type','t1','My Pet Camel',90],['keys',['return'],600],['cap','…then your sentences.',300],['type','t2','My camel is called Sandy. She has one hump and very long eyelashes. She loves eating dates!',35],['cap','Word moves to the next line by itself.']],{noCursor:true})},
 {h:'Change the font, size and colour',p:`<p>1. <b>Select</b> the words first: drag across them so they turn blue.</p><p>2. On the <b>Home</b> tab, use the <b>font box</b> to change the style, the <b>size box</b> to make it bigger, and the <b>A</b> button to change the colour.</p><div class="tipbox"><b>Remember:</b> always select first, then click the button.</div>`,
  demo:DEMO(()=>wDesk(wordWin(`<p data-k="t1">My Pet Camel</p><p>My camel is called Sandy. She has one hump and very long eyelashes.</p>`)),[['cap','First select the title (drag across it).',300],['to','t1',-6],['fn',async p=>{p.rip('','drag');p.cx+=12;p.c.style.transition='left .8s';p.setCur();await sleep(300);p.q('t1').classList.add('hlt');await sleep(700);p.c.style.transition=''}],['cap','Click the size box and choose 28.',300],['to','size'],['click'],['set','size','28'],['style','t1',{fontSize:'2.9cqw',fontWeight:'700'},500],['cap','Click A to change the colour.',300],['to','color'],['click'],['style','t1',{color:'#E0463E'},600],['cap','Choose a fun font.',300],['to','font'],['click'],['set','font','Comic Sans MS'],['style','t1',{fontFamily:'"Comic Sans MS","Comic Neue",cursive'},500],['cls','t1','hlt',false,300],['cap','A big, colourful title!']],{start:[50,60]})},
 {h:'Save your work',p:`<p>Press <kbd>⌘</kbd> + <kbd>S</kbd>. A box appears:</p><p>1. <b>{{Save As||File name}}:</b> type a name, like <b>My Pet Camel</b>.</p><p>2. <b>{{Where||Folder}}:</b> choose your folder <b>[name]'s Work</b>.</p><p>3. Click <b>Save</b>.</p><p>After that, press <kbd>⌘</kbd> + <kbd>S</kbd> every few minutes to keep your changes safe.</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl" style="color:#E0463E">My Pet Camel</p><p>My camel is called Sandy.</p>`)+saveDlg()+menu('wh',[['wh1','Documents'],['wh2',"[name]'s Work"],['wh3','Desktop']],38,17,true,'sv-where')),[['cap','Press ⌘ + S to save.',300],['keys',['⌘','S'],900],['show','save',500],['cap','Type a name for your document.',300],['set','sv-name',''],['type','sv-name','My Pet Camel',80],['cap','Choose the folder: [name]\'s Work.',300],['to','sv-where'],['click'],['show','wh'],['to','wh2'],['cls','wh2','pick'],['click'],['hide','wh'],['set','sv-where',"[name]'s Work"],['cap','Click Save.',300],['to','sv-save'],['click'],['hide','save'],['set','word-title','My Pet Camel'],['cap','Saved! The name is now at the top of the window.']],{start:[50,60]})}
],
mac:['Open Word and create a Blank document.','Type a title and 3 sentences about any animal.','Make the title big and colourful.','Save it as My first document in [name]\'s Work (⌘ + S).','Close Word. Then open your document again by double-clicking it in {{Finder||File Explorer}}.'],
practice:[{type:'hot',title:'Find it in Word',build:()=>wDesk(wordWin(`<p class="ttl">My Pet Camel</p><p>My camel is called Sandy.</p>`)),qs:[['Click the <b>font</b> box (where the font name is).','font'],['Click the <b>size</b> box.','size'],['Click the button that makes words <b>bold</b>.','bold'],['Click the button that changes the <b>colour</b>.','color'],['Click the <b>Insert</b> tab.','t-insert'],['Click the white <b>page</b> where you type.','doc']]},{type:'editor',title:'Practise in Mini Word',intro:'This works like Word. Select the title, then make it bigger and change its colour and font.',text:'<p><b>My Pet Camel</b></p><p>My camel is called Sandy. She has one hump and very long eyelashes. She loves eating dates!</p>'}],
challenge:'Write 5 sentences about your dream pet. Give it a big, colourful title with a fun font, and save it in [name]\'s Work.',
tell:'Show where you saved your document and open it again.'});

L({id:'b16',t:'Formatting like a pro',goal:'Use bold, italic, underline, alignment, bullets and spell check.',warm:'typing',warmLevel:3,
learn:[
 {h:'Bold, italic and underline',p:`<p>Select the words, then click:</p><ul><li><b>B</b> for <b>bold</b> (thick): <kbd>⌘</kbd> + <kbd>B</kbd></li><li><i>I</i> for <i>italic</i> (leaning): <kbd>⌘</kbd> + <kbd>I</kbd></li><li><u>U</u> for <u>underline</u>: <kbd>⌘</kbd> + <kbd>U</kbd></li></ul><p>Click the same button again to switch it off.</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p>Camels are <span data-k="w1">amazing</span> animals. They live in the <span data-k="w2">desert</span> and can go days <span data-k="w3">without water</span>.</p>`)),[['to','w1'],['dbl'],['cls','w1','hlt'],['cap','Click <b>B</b> for bold.',300],['to','bold'],['click'],['cls','bold','on'],['style','w1',{fontWeight:'700'}],['cls','w1','hlt',false,200],['cls','bold','on',false,300],['to','w2'],['dbl'],['cls','w2','hlt'],['cap','Click <b>I</b> for italic.',300],['to','ital'],['click'],['style','w2',{fontStyle:'italic'}],['cls','w2','hlt',false,300],['to','w3'],['dbl'],['cls','w3','hlt'],['cap','Click <b>U</b> for underline.',300],['to','und'],['click'],['style','w3',{textDecoration:'underline'}],['cls','w3','hlt',false,300],['cap','Bold, italic and underline!']],{start:[50,60]})},
 {h:'Line up your text',p:`<p>The alignment buttons move text <b>left</b>, to the <b>centre</b>, or to the <b>right</b>.</p><p>Titles look great in the centre!</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl" data-k="t1">All About Camels</p><p>Camels are amazing animals.</p>`)),[['to','t1',-4],['click'],['cls','t1','hlt'],['cap','Click the centre button.',300],['to','al-center'],['click'],['style','t1',{textAlign:'center'},700],['cap','Now it\'s in the middle. Try right…',300],['to','al-right'],['click'],['style','t1',{textAlign:'right'},900],['to','al-center'],['click'],['style','t1',{textAlign:'center'}],['cls','t1','hlt',false],['cap','Centre looks best for titles.']],{start:[50,60]})},
 {h:'Make a bullet list',p:`<p>Lists are easier to read with <b>bullets</b> (dots). Select your lines, then click the <b>bullets</b> button. Or click it first, then type: each <kbd>return</kbd> makes a new bullet.</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl">Camel facts</p><div data-k="lst"><p>One hump</p><p>Long eyelashes</p><p>Loves dates</p></div>`)),[['to','lst'],['fn',async p=>{p.rip('','drag');p.q('lst').classList.add('hlt');await sleep(600)}],['cap','Click the bullets button.',300],['to','bullets'],['click'],['set','lst','<ul style="margin:0;padding-left:2.4cqw"><li>One hump</li><li>Long eyelashes</li><li>Loves dates</li></ul>',400],['cls','lst','hlt',false],['cap','A neat bullet list!']],{start:[50,60]})},
 {h:'Fix spelling mistakes',p:`<p>A <b>red wavy line</b> under a word means Word thinks it's spelled wrong.</p><p><b>Right-click</b> the word and choose the correct spelling from the list.</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p>My <span class="squig" data-k="bad">favourit</span> food is pizza.</p>`)+menu('sp',[['sp1','<b>favourite</b>'],['sp2','favourites'],'-',['sp3','Ignore']],34,44)),[['cap','See the red wavy line?',900],['to','bad'],['cap','Right-click the word…',300],['rclick'],['show','sp'],['cap','…and choose the right spelling.',300],['to','sp1'],['cls','sp1','pick'],['click'],['hide','sp'],['set','bad','favourite'],['cls','bad','squig',false],['cap','Fixed! No more red line.']],{start:[50,60]})}
],
mac:['Open your document from the last lesson.','Make the title bold and centred.','Make one word italic and one word underlined.','Add a bullet list of 3 facts.','Fix any red wavy lines, then save (⌘ + S).'],
practice:[{type:'editor',intro:'Try every button! Select words first, then format them. Tick each job when it\'s done.',text:'<p>my favourite foods</p><p>pizza</p><p>mango</p><p>chocolate cake</p><p>I really love eating with my family on Fridays.</p>',tasks:['Make "my favourite foods" bold and centred','Turn the 3 foods into a bullet list','Make "Fridays" italic','Change the colour of one word','Undo something with ⌘ + Z']}],
challenge:'Write a list of your 5 favourite foods with bullets, under a bold, centred title. Check there are no red wavy lines.',
tell:'Show how you fixed a spelling mistake with a right-click.'});

L({id:'b17',t:'Pictures & tables',goal:'Add pictures and tables to make an "All About Me" page.',warm:'typing',warmLevel:3,
learn:[
 {h:'Insert a picture',p:`<p>1. Click the <b>Insert</b> tab at the top.</p><p>2. Click <b>Pictures</b> → <b>{{Picture from File…||This Device…}}</b></p><p>3. Find your picture (maybe in your Pictures folder) and click <b>Insert</b>.</p><div class="tipbox"><b>Even easier:</b> drag a picture from {{Finder||File Explorer}} straight onto the page.</div>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl">All About Me</p><p data-k="pl">&nbsp;</p>`)+menu('pm',[['pm1','{{Photo Browser…||Stock Images…}}'],['pm2','{{Picture from File…||This Device…}}'],['pm3','{{Stock Images…||Online Pictures…}}']],12,20,true,'i-pics')),[['cap','Click the <b>Insert</b> tab.',300],['to','t-insert'],['click'],['cls','t-home','on',false,50],['cls','t-insert','on'],['set','rtools',insertTools,300],['cap','Click <b>Pictures</b>.',300],['to','i-pics'],['click'],['show','pm'],['to','pm2'],['cls','pm2','pick'],['click'],['hide','pm'],['cap','Choose your picture and click Insert.',700],['set','pl','<span class="imgin" data-k="img" style="display:inline-block;width:16cqw;height:11cqw"></span>',400],['cap','Your picture is on the page!']],{start:[50,60]})},
 {h:'Make it bigger or smaller',p:`<p>Click the picture. Little circles appear around it.</p><p>Drag a <b>corner</b> circle to resize it. Corners keep the picture's shape. The middle circles squash it, so avoid those!</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl">All About Me</p><p><span class="imgin" data-k="img" style="display:inline-block;width:14cqw;height:9.6cqw"><i class="hdl" style="left:-.6cqw;top:-.6cqw"></i><i class="hdl" style="right:-.6cqw;top:-.6cqw"></i><i class="hdl" style="left:-.6cqw;bottom:-.6cqw"></i><i class="hdl" data-k="hc" style="right:-.6cqw;bottom:-.6cqw"></i></span></p>`)),[['cap','Grab a <b>corner</b> circle…',300],['to','hc'],['fn',async p=>{p.rip('','press & hold');await sleep(400);const i=p.q('img');i.style.width='24cqw';i.style.height='16.5cqw';p.c.style.transition='left .8s,top .8s';p.cx+=10;p.cy+=11;p.setCur();await sleep(900);p.c.style.transition='';p.rip('','let go')}],['cap','…and drag. It grows but keeps its shape!']],{start:[50,70]})},
 {h:'Add a table',p:`<p>A <b>table</b> is a grid of boxes, great for lists of facts.</p><p>1. <b>Insert</b> tab → <b>Table</b>.</p><p>2. Move over the little grid to choose how many columns and rows. We want <b>2 columns and 4 rows</b>.</p><p>3. Click.</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl">All About Me</p><div data-k="tb"></div>`,{tab:'Insert'})+`<div class="tgrid off" data-k="tg" data-anchor="i-table" style="left:24%;top:23%">${Array.from({length:48},(_,i)=>`<i data-k="g${i}"></i>`).join('')}<b data-k="gl">Table</b></div>`),[['cap','Click <b>Table</b>.',300],['to','i-table'],['click'],['show','tg'],['cap','Move over the grid: 2 across, 4 down.',300],['to','g0'],['fn',async p=>{const on=[];for(let r=0;r<4;r++)for(let c=0;c<2;c++){on.push(r*8+c)}for(const n of on){p.q('g'+n).classList.add('on');p.q('gl').textContent=`${Math.floor(n/8)+1}×${n%8+1}`;const[x,y]=p.pos('g'+n);p.cx=x;p.cy=y;p.setCur();await sleep(220)}p.q('gl').textContent='2 × 4 Table'}],['click'],['hide','tg'],['set','tb','<table class="tbl"><tr><td></td><td></td></tr><tr><td></td><td></td></tr><tr><td></td><td></td></tr><tr><td></td><td></td></tr></table>'],['cap','A table with 2 columns and 4 rows!']],{start:[50,60]})},
 {h:'Type in your table',p:`<p>Click inside a box and type. Press <kbd>tab</kbd> to jump to the next box. When you reach the last box, <kbd>tab</kbd> adds a new row!</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl">All About Me</p><table class="tbl"><tr><td data-k="c1"></td><td data-k="c2"></td></tr><tr><td data-k="c3"></td><td data-k="c4"></td></tr><tr><td data-k="c5"></td><td data-k="c6"></td></tr></table>`)),[['to','c1'],['click'],['type','c1','Favourite colour',50],['keys',['tab'],500],['type','c2','Purple',60],['keys',['tab'],500],['type','c3','Favourite food',50],['keys',['tab'],500],['type','c4','Pizza',60],['keys',['tab'],500],['type','c5','Hobby',60],['keys',['tab'],500],['type','c6','Drawing',60],['cap','Tab jumps from box to box.']],{start:[50,60]})}
],
mac:['Open Word and make a new document called All About Me.','Add a picture you like.','Resize it with a corner circle.','Add a table with 2 columns and 4 rows: favourite colour, food, animal and hobby.','Save it in [name]\'s Work.'],
practice:[{type:'hot',title:'Insert tab explorer',build:()=>wDesk(wordWin(`<p class="ttl">All About Me</p>`,{tab:'Insert'})),qs:[['Click <b>Pictures</b>.','i-pics'],['Click <b>Table</b>.','i-table'],['Click <b>Shapes</b>.','i-shapes'],['Click the <b>Home</b> tab.','t-home'],['Click the button that <b>closes</b> this window.','word-close']]}],
challenge:'Finish your "All About Me" page: a title, a picture and a table with at least 4 rows. Make it look beautiful!',
tell:'Show your All About Me page and how you resized the picture.'});

L({id:'b18',t:'Word project: my story',goal:'Plan, write and check a one-page story, then save it as a PDF and print it.',warm:'typing',warmLevel:3,
learn:[
 {h:'Plan your story',p:`<p>Every good story has three parts. Plan them before you type:</p><div class="storymap"><div><b>Beginning</b>Who is in the story? Where are they?</div><div><b>Middle</b>What problem happens? What do they do?</div><div><b>End</b>How is the problem solved? How do they feel?</div></div><p style="margin-top:12px">Need an idea? <i>The camel who was scared of sand. A cat who found a door in the Burj Khalifa. The day my computer came alive.</i></p>`},
 {h:'Write and check',p:`<ul><li>A <b>title</b> at the top: bold and centred.</li><li><b>Three paragraphs</b>: beginning, middle, end.</li><li><b>One picture</b> that matches the story.</li><li>Fix every <b>red wavy line</b>.</li><li><b>Read it out loud</b>. Does it make sense?</li><li>Save often with <kbd>⌘</kbd> + <kbd>S</kbd>.</li></ul>`},
 {h:'Save as a PDF',p:`<p>A <b>PDF</b> is a file that looks exactly the same on every computer and phone. Great for sending!</p>{{<p>1. <b>File</b> → <b>Save As…</b></p><p>2. Click <b>File Format</b> and choose <b>PDF</b>.</p><p>3. Click <b>Export</b>.</p>||<p>1. <b>File</b> → <b>Save As</b> → <b>Browse</b>.</p><p>2. Click <b>Save as type</b> and choose <b>PDF</b>.</p><p>3. Click <b>Save</b>.</p>}}`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl" style="text-align:center">The Brave Little Camel</p><p>Once upon a time…</p>`,{title:'The Brave Little Camel'})+wordFileMenu()+saveDlg({name:'The Brave Little Camel',where:"[name]'s Work",format:'Word Document (.docx)',btn:'{{Export||Save}}'})+menu('fmt',[['fmt1','Word Document (.docx)'],['fmt2','<b>PDF</b>'],['fmt3','Web Page (.htm)']],40,22,true,'sv-fmt')),[['cap','Click <b>File</b>, then <b>Save As…</b>',300],['to','m-file'],['click'],['cls','m-file','pick'],['show','fmenu'],['to','fm-saveas'],['cls','fm-saveas','pick'],['click'],['hide','fmenu'],['cls','m-file','pick',false],['show','save'],['cap','Click <b>{{File Format||Save as type}}</b>…',300],['to','sv-fmt'],['click'],['show','fmt'],['cap','…and choose <b>PDF</b>.',300],['to','fmt2'],['cls','fmt2','pick'],['click'],['hide','fmt'],['set','sv-fmt','PDF'],['to','sv-save'],['click'],['hide','save'],['cap','Done! Now you have a PDF of your story.']],{start:[50,60]})},
 {h:'Print it',p:`<p>Press <kbd>⌘</kbd> + <kbd>P</kbd>. Check the preview, choose how many <b>copies</b>, then click <b>Print</b>.</p><div class="tipbox"><b>Ask a grown-up first:</b> printers use paper and ink.</div>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl" style="text-align:center">The Brave Little Camel</p><p>Once upon a time…</p>`,{title:'The Brave Little Camel'})+`<div class="pdlg off" data-k="pr"><div class="pvw"><div class="pg"><b>The Brave Little Camel</b><br>Once upon a time…</div><div style="display:flex;flex-direction:column;gap:1cqw;flex:1"><div class="r"><b>Printer:</b><span class="fld">Home Printer</span></div><div class="r"><b>Copies:</b><span class="fld" data-k="copies">1</span></div><div class="r"><b>Pages:</b><span class="fld">All</span></div></div></div><div class="row"><span class="b2">Cancel</span><span class="b2 pri" data-k="prgo">Print</span></div></div>`),[['cap','Press ⌘ + P.',300],['keys',['⌘','P'],900],['show','pr',600],['cap','Check the preview and the number of copies.',1400],['to','copies'],['click'],['set','copies','2'],['to','prgo'],['click'],['hide','pr'],['cap','Printing! Go and collect your story.']],{start:[50,60]})}
],
mac:['Plan your story on paper: beginning, middle, end.','Write it in Word with a title, 3 paragraphs and a picture.','Fix all spelling and read it out loud.','Save it, then save a PDF copy.','Print it (ask first) with ⌘ + P.'],
practice:[{type:'quiz',title:'Story checklist quiz',qs:[
 {q:'What are the three parts of a story?',a:['Beginning, middle, end','Title, picture, font','Red, yellow, green'],c:0},
 {q:'Why save as a PDF?',a:['It looks the same on every computer','It makes the text bigger','It deletes mistakes'],c:0},
 {q:'What is the shortcut to print?',a:['⌘ + P','⌘ + T','⌘ + Q'],c:0},
 {q:'What does a red wavy line mean?',a:['A spelling mistake','A link','A new page'],c:0},
 {q:'How often should you save?',a:['Every few minutes with ⌘ + S','Only at the end','Never'],c:0,why:'Then you never lose your work.'}]}],
challenge:'Finish your one-page story and print it. Put it on the fridge!',
tell:'Read your story out loud to your family.'});

L({id:'b19',t:'PowerPoint basics',goal:'Make a presentation: pick a design, add a title and new slides.',warm:'typing',warmLevel:3,
learn:[
 {h:'Open PowerPoint and pick a design',p:`<p>Click the orange <b>P</b> and choose <b>Blank Presentation</b>.</p><p>Then click the <b>Design</b> tab and click a design you like. All your slides get matching colours!</p>`,
  demo:DEMO(()=>pDesk(pptWin()),[['cap','Click the <b>Design</b> tab.',300],['to','t-design'],['click'],pptTabsOn('Design'),['set','rtools',`<span class="designs">${['#fff','linear-gradient(135deg,#0F4C81,#1B7FBF)','linear-gradient(135deg,#FFF1C9,#FFC8A2)','linear-gradient(135deg,#1FA971,#0E7A57)'].map((b,i)=>`<span data-k="des${i}" style="background:${b}"></span>`).join('')}</span>`,300],['cap','Click a design you like.',300],['to','des1'],['click'],['cls','slide','th1',true,800],['cap','Or try another one…',300],['to','des2'],['click'],['cls','slide','th1',false,0],['cls','slide','th2',true,800],['cap','Pick your favourite!']],{start:[50,60]})},
 {h:'Add your title',p:`<p>Click inside <b>"Click to add title"</b> and type your title.</p><p>Click inside <b>"Click to add subtitle"</b> and type your name.</p>`,
  demo:DEMO(()=>pDesk(pptWin({theme:'th1'})),[['to','ptitle'],['click'],['set','ptitle',''],['cls','ptitle','fill'],['type','ptitle','My Favourite Animal',80],['to','psub'],['click'],['set','psub',''],['cls','psub','fill'],['type','psub','by [name]',80],['cap','Your title slide is ready!']],{start:[50,70]})},
 {h:'Add a new slide',p:`<p>Click <b>New Slide</b> on the Home tab (or press {{<kbd>⇧</kbd> + <kbd>⌘</kbd> + <kbd>N</kbd>||<kbd>Ctrl</kbd> + <kbd>M</kbd>}}). A new slide appears in the list on the left.</p><p>The small arrow next to New Slide lets you pick a <b>layout</b>: title only, title and text, two pictures and more.</p>`,
  demo:DEMO(()=>pDesk(pptWin({theme:'th1',slide:'<div class="ph fill">My Favourite Animal</div><div class="ph sub fill">by [name]</div>',thumbTxt:['My Favourite Animal']})),[['cap','Click <b>New Slide</b>.',300],['to','p-new'],['click'],['fn',async p=>{p.q('th1').classList.remove('on');p.q('thumbs').insertAdjacentHTML('beforeend','<div class="th on" data-n="2" data-k="th2"></div>')},300],['set','slide','<div class="ph" data-k="t2" style="width:80%">Click to add title</div><div class="ph sub" style="width:80%;height:45%">Click to add text</div>',300],['cap','Slide 2! Now type a title.',300],['to','t2'],['click'],['set','t2',''],['cls','t2','fill'],['type','t2','What it looks like',70],['set','th2','What it looks like'],['cap','Your slides are listed on the left.']],{start:[50,60]})},
 {h:'Move slides around',p:`<p>The list on the left shows all your slides in order. To change the order, <b>drag</b> a slide up or down in that list and let go.</p><p>To delete a slide, click it in the list and press <kbd>delete</kbd>.</p>`,
  demo:DEMO(()=>pDesk(pptWin({theme:'th1',slides:3,thumbTxt:['My Favourite Animal','Where it lives','Fun facts'],slide:'<div class="ph fill">Fun facts</div>'})),[['cap','Let\'s move "Fun facts" to be slide 2.',600],['drag','th3','th2',{dy:-3,drop:false}],['fn',async p=>{const t3=p.q('th3'),t2=p.q('th2');t2.parentNode.insertBefore(t3,t2);[...p.q('thumbs').children].forEach((t,i)=>t.dataset.n=i+1)},300],['cap','Now "Fun facts" is slide 2!']],{start:[50,60]})}
],
mac:['Open PowerPoint and start a Blank Presentation.','Pick a design from the Design tab.','Type a title and your name on slide 1.','Add 2 more slides with New Slide and give them titles.','Drag a slide to change the order. Save it as My first slides.'],
practice:[{type:'hot',title:'PowerPoint explorer',build:()=>pDesk(pptWin({slides:3,thumbTxt:['Title','Facts','The end']})),qs:[['Click <b>New Slide</b>.','p-new'],['Click the <b>Design</b> tab.','t-design'],['Click <b>slide 2</b> in the list on the left.','th2'],['Click the <b>title box</b> on the slide.','ptitle'],['Click the <b>Slide Show</b> tab.','t-slide-show'],['Click the <b>Transitions</b> tab.','t-transitions']]}],
challenge:'Make a 3-slide presentation called "My Family": a title slide, a slide about the people, and a slide about what you like doing together.',
tell:'Show how to add a new slide and change the design.'});

L({id:'b20',t:'Pictures & animation',goal:'Add pictures, transitions between slides and animations that make things appear.',warm:'typing',warmLevel:3,
learn:[
 {h:'Add a picture',p:`<p>Just like in Word: <b>Insert</b> tab → <b>Pictures</b> → <b>{{Picture from File…||This Device…}}</b>, choose your picture, click <b>Insert</b>.</p><p>Drag the picture to move it. Drag a <b>corner</b> to resize it.</p>`,
  demo:DEMO(()=>pDesk(pptWin({theme:'th2',slide:'<div class="ph fill" style="position:absolute;top:8%">The Arabian Oryx</div><span class="imgin off" data-k="img" style="position:absolute;left:30%;top:35%;width:40%;height:50%"></span>',tools:insertTools,tab:'Insert'})+menu('pm',[['pm1','{{Photo Browser…||Stock Images…}}'],['pm2','{{Picture from File…||This Device…}}']],12,20,true,'i-pics')),[['to','i-pics'],['click'],['show','pm'],['to','pm2'],['cls','pm2','pick'],['click'],['hide','pm'],['show','img',700],['cap','Now drag it to a nice spot.',300],['to','img'],['fn',async p=>{p.rip('','press & hold');await sleep(400);const i=p.q('img');i.style.left='52%';p.c.style.transition='left .8s';p.cx+=13;p.setCur();await sleep(900);p.c.style.transition='';p.rip('','let go')}],['cap','Picture added and moved!']],{start:[50,60]})},
 {h:'Transitions: how slides change',p:`<p>A <b>transition</b> is the movement when one slide changes to the next.</p><p>Click a slide, open the <b>Transitions</b> tab and click one, like <b>Fade</b> or <b>Push</b>. It plays a preview straight away.</p>`,
  demo:DEMO(()=>pDesk(pptWin({theme:'th1',slides:2,slide:'<div class="ph fill">My Favourite Animal</div>'})),[['cap','Click the <b>Transitions</b> tab.',300],['to','t-transitions'],['click'],pptTabsOn('Transitions'),['set','rtools',['Fade','Push','Wipe','Reveal'].map((t,i)=>`<span class="rbig" data-k="tr${i}"><span style="width:3cqw;height:2cqw;background:#ddd;border-radius:.3cqw;display:block"></span>${t}</span>`).join(''),300],['cap','Click <b>Push</b> to see it.',300],['to','tr1'],['click'],['cls','tr1','hl',true,200],['fn',async p=>{const s=p.q('slide');s.style.transform='translateX(-110%)';await sleep(650);s.style.transition='none';s.className='slide th2';s.innerHTML='<div class="ph fill">Where it lives</div>';s.style.transform='translateX(110%)';s.getBoundingClientRect();s.style.transition='';s.style.transform='none';await sleep(800)}],['unhl'],['cap','The new slide pushed the old one away!']],{start:[50,60]})},
 {h:'Animations: make things appear',p:`<p>An <b>animation</b> makes one thing on a slide move, like words flying in.</p><p>1. Click the thing you want to animate.</p><p>2. Open the <b>Animations</b> tab.</p><p>3. Click an effect like <b>Appear</b> or <b>Fly In</b>.</p>`,
  demo:DEMO(()=>pDesk(pptWin({theme:'th3',slide:'<div class="ph fill">Fun facts</div><div class="ph sub fill" data-k="fact">Oryx can smell rain from far away!</div>'})),[['to','fact'],['click'],['cls','fact','hlt'],['cap','Open the <b>Animations</b> tab.',300],['to','t-animations'],['click'],pptTabsOn('Animations'),['set','rtools',['Appear','Fade','Fly In','Zoom'].map((t,i)=>`<span class="rbig" data-k="an${i}"><span style="width:2.4cqw;height:2.4cqw;background:#2BB673;border-radius:50%;display:block"></span>${t}</span>`).join(''),300],['cap','Click <b>Fly In</b>.',300],['to','an2'],['click'],['cls','fact','hlt',false],['cls','fact','flyNow',true,1000],['cls','fact','flyNow',false,100],['cap','Whoosh! The fact flies in.']],{start:[50,60]})},
 {h:'Not too many!',p:`<p>Animations are fun, but too many make people dizzy and take attention away from what you're saying.</p><p><b>Good rule:</b> one transition style for the whole show, and at most <b>one animation per slide</b>.</p><div class="tipbox"><b>Preview:</b> click <b>Preview</b> on the Transitions or Animations tab to see it again.</div>`}
],
mac:['Open your presentation from the last lesson.','Add a picture to slide 2 and resize it.','Add a Fade or Push transition to every slide.','Add one Fly In or Appear animation on one slide.','Save your work.'],
practice:[{type:'quiz',title:'Transitions or animations?',qs:[
 {q:'The movement when one slide changes to the next is called…',a:['a transition','an animation','a table'],c:0},
 {q:'Making one sentence fly in is…',a:['an animation','a transition','a design'],c:0},
 {q:'Where do you find Fly In?',a:['Animations tab','Insert tab','File menu'],c:0},
 {q:'How many animations per slide is a good rule?',a:['About one','At least ten','As many as possible'],c:0,why:'Too many make people dizzy!'},
 {q:'How do you resize a picture without squashing it?',a:['Drag a corner circle','Drag a middle circle','Press delete'],c:0}]}],
challenge:'Add a picture to every slide of your "My Family" presentation, and one animation you really like.',
tell:'Explain the difference between a transition and an animation.'});

L({id:'b21',t:'Present it!',goal:'Make 5 slides about your favourite animal and present them.',warm:'typing',warmLevel:3,
learn:[
 {h:'Plan your 5 slides',p:`<div class="recap"><div><b>Slide 1</b>Title: "My Favourite Animal" and your name</div><div><b>Slide 2</b>What it looks like (with a picture)</div><div><b>Slide 3</b>Where it lives and what it eats</div><div><b>Slide 4</b>Three amazing facts (use bullets)</div><div><b>Slide 5</b>Why I love it, and "Thank you!"</div></div><p style="margin-top:12px">Find your facts with a safe search, and check them on two websites!</p>`},
 {h:'Start the slide show',p:`<p>Click the <b>Slide Show</b> tab, then <b>From Beginning</b>. Your slides fill the whole screen.</p><p>Shortcut: {{<kbd>⇧</kbd> + <kbd>⌘</kbd> + <kbd>return</kbd>||<kbd>F5</kbd>}}.</p>`,
  demo:DEMO(()=>pDesk(pptWin({theme:'th1',slides:5,thumbTxt:['My Favourite Animal','Looks','Home','Facts','Thanks'],slide:'<div class="ph fill">My Favourite Animal</div><div class="ph sub fill">by [name]</div>'})+`<div class="showfull off" data-k="sf"><div class="slide th1" data-k="fs"><div class="ph fill" style="font-size:5cqw">My Favourite Animal</div><div class="ph sub fill" style="font-size:2.6cqw">by [name]</div></div></div>`),[['cap','Click the <b>Slide Show</b> tab.',300],['to','t-slide-show'],['click'],pptTabsOn('Slide Show'),['set','rtools',`<span class="rbig" data-k="ss1"><span style="font-size:2.4cqw">▶</span>From Beginning</span><span class="rbig"><span style="font-size:2.4cqw">▷</span>From Current Slide</span>`,300],['cap','Click <b>From Beginning</b>.',300],['to','ss1'],['click'],['curs','none'],['show','sf',900],['cap','Your slides fill the whole screen!']],{start:[50,60]})},
 {h:'Move through your slides',p:`<ul><li><b>Next slide:</b> <kbd>→</kbd>, <kbd>space</kbd> or a click.</li><li><b>Go back:</b> <kbd>←</kbd></li><li><b>Stop the show:</b> <kbd>esc</kbd></li></ul>`,
  demo:DEMO(()=>`<div class="showfull" data-k="sf"><div class="slide th1" data-k="fs"><div class="ph fill" style="font-size:5cqw">My Favourite Animal</div><div class="ph sub fill" style="font-size:2.6cqw">by [name]</div></div></div>`+desk('',{app:'PowerPoint'}),[['cap','Press → for the next slide.',300],['keys',['→'],700],['set','fs','<div class="ph fill" style="font-size:4cqw">What it looks like</div><span class="imgin" style="width:30%;height:40%"></span>'],['cap','Space works too.',300],['keys',['space'],700],['set','fs','<div class="ph fill" style="font-size:4cqw">Where it lives</div><div class="ph sub fill" style="font-size:2.4cqw">In the deserts of Arabia</div>'],['cap','← goes back.',300],['keys',['←'],700],['set','fs','<div class="ph fill" style="font-size:4cqw">What it looks like</div><span class="imgin" style="width:30%;height:40%"></span>'],['cap','{{esc||Esc}} stops the show.',300],['keys',['esc'],700],['hide','sf',600],['cap','Back to editing.']],{noCursor:true})},
 {h:'Presenter tips',p:`<ul><li><b>Stand tall</b> and smile.</li><li><b>Look at your audience</b>, not only at the screen.</li><li>Speak <b>slowly and loudly</b>.</li><li>Don't read every word. The slides are reminders; you tell the story!</li><li>Practise once before the real show.</li><li>At the end, ask: <b>"Any questions?"</b></li></ul>`}
],
mac:['Make 5 slides about your favourite animal (use the plan).','Add pictures, one transition style, and one animation.','Practise the slide show once by yourself.','Present it to your family!'],
practice:[{type:'quiz',title:'Slide show keys',qs:[
 {q:'Which key goes to the next slide?',a:['→ or space','{{delete||Backspace}}','⌘ + Q'],c:0},
 {q:'Which key stops the slide show?',a:['{{esc||Esc}}','{{return||Enter}}','tab'],c:0},
 {q:'Where do you find "From Beginning"?',a:['Slide Show tab','Design tab','Insert tab'],c:0},
 {q:'What should you do while presenting?',a:['Look at your audience and speak slowly','Read every word very fast','Hide behind the screen'],c:0}]}],
challenge:'Give your "My Favourite Animal" presentation to your family. Ask them for one thing they liked and one thing to make even better.',
tell:'This is the Show & Tell: present your 5 slides!'});

/* ============================== UNIT 4: Smart skills ============================== */
L({id:'b22',t:'Excel: meet the grid',goal:'Understand cells, rows and columns, and type information into Excel.',warm:'typing',warmLevel:4,
learn:[
 {h:'A page of boxes',p:`<p>Open <b>Excel</b> (the green <b>X</b>) and choose <b>Blank Workbook</b>.</p><p>The page is a big grid of boxes called <b>cells</b>.</p><ul><li><b>Columns</b> go up and down and have <b>letters</b>: A, B, C…</li><li><b>Rows</b> go across and have <b>numbers</b>: 1, 2, 3…</li></ul>`,
  demo:DEMO(()=>xDesk(excelWin({})),[['cls','col-B','on'],['fn',async p=>{for(let r=1;r<=9;r++){p.q('c-B'+r)?.classList.add('rng')}}],['tag','col-B','Column B'],['cap','A <b>column</b> goes up and down. This is column B.',1800],['untag'],clearRng,['cls','col-B','on',false],['cls','row-3','on'],['fn',async p=>{'ABCDE'.split('').forEach(c=>p.q('c-'+c+'3')?.classList.add('rng'))}],['tag','row-3','Row 3'],['cap','A <b>row</b> goes across. This is row 3.',1800],['untag'],clearRng,['cls','row-3','on',false],['cls','c-B3','cs'],['tag','c-B3','Cell B3'],['cap','Where they meet is a <b>cell</b>: B3!',1800],['untag']],{noCursor:true})},
 {h:'Every cell has a name',p:`<p>A cell's name is its <b>column letter</b> + its <b>row number</b>.</p><p>Column C, row 5 → <b>C5</b>. Like a treasure map!</p><p>The name of the cell you clicked shows in the <b>Name Box</b> at the top left.</p>`,
  demo:DEMO(()=>xDesk(excelWin({})),[['to','c-A1'],['click'],['cls','c-A1','cs'],['set','x-name','A1'],['cap','Column A, row 1 = <b>A1</b>',1400],['cls','c-A1','cs',false,0],['to','c-C5'],['click'],['cls','c-C5','cs'],['set','x-name','C5'],['cap','Column C, row 5 = <b>C5</b>',1400],['cls','c-C5','cs',false,0],['to','c-D2'],['click'],['cls','c-D2','cs'],['set','x-name','D2'],['hl','x-name',100],['cap','The Name Box shows <b>D2</b>.',1400],['unhl']],{start:[50,60]})},
 {h:'Type into cells',p:`<p>Click a cell and type. Then:</p><ul><li><kbd>return</kbd> moves <b>down</b> one cell.</li><li><kbd>tab</kbd> moves <b>right</b> one cell.</li></ul><p>Made a mistake? Click the cell and type again. It replaces what was there.</p>`,
  demo:DEMO(()=>xDesk(excelWin({})),[['to','c-A1'],['click'],['cls','c-A1','cs'],['type','c-A1','Fruit',80],['keys',['tab'],500],['cls','c-A1','cs',false,0],['cls','c-B1','cs'],['type','c-B1','Votes',80],['keys',['return'],500],['cls','c-B1','cs',false,0],['to','c-A2'],['click'],['cls','c-A2','cs'],['type','c-A2','Mango',80],['keys',['tab'],400],['cls','c-A2','cs',false,0],['cls','c-B2','cs'],['type','c-B2','6',80],['style','c-B2',{justifyContent:'flex-end'}],['keys',['return'],400],['cls','c-B2','cs',false,0],['cls','c-B3','cs'],['cap','Tab goes right, {{return||Enter}} goes down.']],{start:[50,60]})},
 {h:'Make a column wider',p:`<p>Words too long for the cell? Move the pointer to the line <b>between two column letters</b> at the top. When it changes to a ⟷ arrow, <b>double-click</b>. The column fits your words!</p>`,
  demo:DEMO(()=>xDesk(excelWin({A1:'Favourite drink',A2:'Strawberry milkshake',A3:'Mango lassi',B1:'Votes',B2:7,B3:5})),[['cap','The words are cut off…',1000],toEdge('col-B'),['cap','Double-click the line between A and B.',300],['dbl'],['style','grid',{gridTemplateColumns:'3cqw 2.2fr repeat(4,minmax(0,1fr))'},900],['cap','Now everything fits!']],{start:[50,60]})}
],
mac:['Open Excel and choose Blank Workbook.','Click on cell C5. Check the Name Box says C5.','Type Fruit in A1 and Votes in B1.','Type 5 fruits under Fruit, and a number of votes next to each.','Make column A wider. Save as Fruit survey.'],
practice:[{type:'hot',title:'Cell treasure hunt',intro:'Click the cell with the right name. Remember: letter first, then number.',build:()=>xDesk(excelWin(fruitData)),qs:[['Click cell <b>B3</b>.','c-B3'],['Click cell <b>A5</b>.','c-A5'],['Click cell <b>D1</b>.','c-D1'],['Click cell <b>C7</b>.','c-C7'],['Click the cell that says <b>Strawberry</b>.','c-A5'],['Click the <b>column letter</b> C.','col-C'],['Click the <b>row number</b> 4.','row-4']]}],
challenge:'Ask 5 people their favourite fruit. Put the results in Excel: fruit names in column A and votes in column B.',
tell:'Explain what a cell, a row and a column are, and point to cell B2.'});

L({id:'b23',t:'Simple formulas',goal:'Make Excel do maths for you with formulas and SUM.',warm:'typing',warmLevel:4,
learn:[
 {h:'Formulas start with =',p:`<p>A <b>formula</b> tells Excel to do maths. It always starts with <b>=</b></p><p>Type <b>=2+3</b> in a cell and press <kbd>return</kbd>. The cell shows <b>5</b>!</p><p>Excel uses <b>+</b> add, <b>-</b> take away, <b>*</b> times and <b>/</b> divide.</p>`,
  demo:DEMO(()=>xDesk(excelWin({})),[['to','c-B2'],['click'],['cls','c-B2','cs'],['set','x-name','B2'],['type','c-B2','=2+3',140],['set','x-fx','=2+3'],['keys',['return'],700],['set','c-B2','5'],['style','c-B2',{justifyContent:'flex-end'}],['cap','Excel did the maths: 5!',900],['to','c-B3'],['click'],['cls','c-B2','cs',false,0],['cls','c-B3','cs'],['type','c-B3','=6*4',140],['keys',['return'],700],['set','c-B3','24'],['style','c-B3',{justifyContent:'flex-end'}],['cap','6 times 4 = 24. Excel is a super calculator!']],{start:[50,60]})},
 {h:'Use cell names',p:`<p>The real magic: use <b>cell names</b> in formulas. <b>=B2+B3</b> adds whatever is in B2 and B3.</p><p>Change a number, and the answer <b>updates by itself</b>!</p>`,
  demo:DEMO(()=>xDesk(excelWin({A1:'Day',B1:'Pages read',A2:'Monday',B2:5,A3:'Tuesday',B3:3,A4:'Total'})),[['to','c-B4'],['click'],['cls','c-B4','cs'],['type','c-B4','=B2+B3',110],['cls','c-B2','rng'],['cls','c-B3','rng',true,600],['keys',['return'],700],clearRng,['set','c-B4','8'],['style','c-B4',{justifyContent:'flex-end',fontWeight:'700'}],['cap','5 + 3 = 8. Now change Monday to 10…',500],['to','c-B2'],['click'],['cls','c-B4','cs',false,0],['cls','c-B2','cs'],['set','c-B2',''],['type','c-B2','10',150],['keys',['return'],500],['hl','c-B4',100],['set','c-B4','13',900],['unhl'],['cap','The total changed to 13 by itself!']],{start:[50,60]})},
 {h:'SUM adds a whole list',p:`<p>Adding lots of cells? Use <b>SUM</b>:</p><p><b>=SUM(B2:B6)</b></p><p>The <b>colon ( : )</b> means "from B2 <b>to</b> B6". Excel adds everything in between.</p>`,
  demo:DEMO(()=>xDesk(excelWin({A1:'Day',B1:'Pocket money',A2:'Sun',B2:5,A3:'Mon',B3:2,A4:'Tue',B4:4,A5:'Wed',B5:3,A6:'Thu',B6:6,A7:'Total'})),[['to','c-B7'],['click'],['cls','c-B7','cs'],['type','c-B7','=SUM(B2:B6)',100],selCells(['B2','B3','B4','B5','B6']),['cap','B2:B6 means B2, B3, B4, B5 and B6.',1000],['keys',['return'],700],clearRng,['set','c-B7','20'],['style','c-B7',{justifyContent:'flex-end',fontWeight:'700'}],['cap','Total pocket money: 20!']],{start:[50,60]})},
 {h:'AutoSum: the lazy button',p:`<p>Click the empty cell under your numbers, then click <b>AutoSum Σ</b> on the Home tab. Excel writes the SUM formula for you! Press <kbd>return</kbd>.</p>`,
  demo:DEMO(()=>xDesk(excelWin({A1:'Day',B1:'Minutes read',A2:'Sun',B2:20,A3:'Mon',B3:15,A4:'Tue',B4:30,A5:'Wed',B5:10,A6:'Total'})),[['to','c-B6'],['click'],['cls','c-B6','cs'],['cap','Click <b>AutoSum Σ</b>.',300],['to','x-sum'],['click'],['set','c-B6','=SUM(B2:B5)'],selCells(['B2','B3','B4','B5'],80),['cap','Excel wrote the formula for you!',1000],['keys',['return'],700],clearRng,['set','c-B6','75'],['style','c-B6',{justifyContent:'flex-end',fontWeight:'700'}],['cap','75 minutes of reading. Well done!']],{start:[50,60]})}
],
mac:['Open Excel. In A1 type =2+3 and press {{return||Enter}}.','Make a pocket money table: days in column A, amounts in column B.','Under the amounts, type =SUM(B2:B6) (or use AutoSum).','Change one amount and watch the total change by itself.','Save it as Pocket money.'],
practice:[{type:'sheet',title:'Pocket money calculator',intro:'Click a cell to type. Formulas start with <b>=</b>. Press <kbd>return</kbd> when you finish typing.',cols:['A','B'],rows:[['Day','Money'],['Sunday',5],['Monday',2],['Tuesday',4],['Wednesday',3],['Thursday',6],['Total',''],['Double it!','']],res:['B7','B8'],tasks:[{cell:'B7',expect:20,text:'In B7, add up B2 to B6 with =SUM(B2:B6)'},{cell:'B8',expect:40,text:'In B8, double the total with =B7*2'}]}],
challenge:'Make a table of how many minutes you read each day this week, and use SUM to find the total.',
tell:'Show how the total changes by itself when you change a number.'});

L({id:'b24',t:'Make a chart',goal:'Turn a table of numbers into a colourful chart.',warm:'typing',warmLevel:4,
learn:[
 {h:'Select your data',p:`<p>Drag across the cells with your data, <b>including the headings</b>. For example, from <b>A1</b> to <b>B5</b>. They turn a light colour.</p>`,
  demo:DEMO(()=>xDesk(excelWin(fruitData)),[['to','c-A1'],['cap','Press on A1 and drag to B5.',300],['fn',async p=>{p.rip('','press & hold');const cells=['A1','B1','A2','B2','A3','B3','A4','B4','A5','B5'];for(const c of cells){p.q('c-'+c).classList.add('rng')}const[x,y]=p.pos('c-B5');p.c.style.transition='left 1s,top 1s';p.cx=x;p.cy=y;p.setCur();await sleep(1100);p.c.style.transition='';p.rip('','let go')}],['cap','Your data is selected!']],{start:[50,60]})},
 {h:'Insert a chart',p:`<p>1. Click the <b>Insert</b> tab.</p><p>2. Click the <b>Chart</b> button (the little column picture).</p><p>3. Choose <b>Clustered Column</b>. Your chart appears!</p>`,
  demo:DEMO(()=>xDesk(excelWin(fruitData,{extra:`<div class="xchart off" data-k="ch"><div class="ct" data-k="ctt">Votes</div><div class="bars"><i data-k="b1" style="height:0"></i><i data-k="b2" style="height:0;background:#F0A500"></i><i data-k="b3" style="height:0;background:#E0463E"></i><i data-k="b4" style="height:0;background:#12966A"></i></div><div class="lbl"><span>Mango</span><span>Banana</span><span>Apple</span><span>Strawb.</span></div></div>`})),[selCells(['A1','B1','A2','B2','A3','B3','A4','B4','A5','B5'],40),['to','t-insert'],['click'],['cls','t-home','on',false,0],['cls','t-insert','on'],['set','rtools',insertTools,300],['to','i-chart'],['click'],['show','ch',500],['style','b1',{height:'75%'},0],['style','b2',{height:'50%'},0],['style','b3',{height:'62%'},0],['style','b4',{height:'100%'},900],['cap','A column chart! The tallest bar is the favourite.']],{start:[50,60]})},
 {h:'Give it a title',p:`<p>Click the words <b>Chart Title</b> at the top of the chart, select them and type your own title, like <b>Our favourite fruits</b>.</p>`,
  demo:DEMO(()=>xDesk(excelWin(fruitData,{extra:`<div class="xchart" data-k="ch"><div class="ct" data-k="ctt">Chart Title</div><div class="bars"><i style="height:75%"></i><i style="height:50%;background:#F0A500"></i><i style="height:62%;background:#E0463E"></i><i style="height:100%;background:#12966A"></i></div><div class="lbl"><span>Mango</span><span>Banana</span><span>Apple</span><span>Strawb.</span></div></div>`})),[['to','ctt'],['click'],['cls','ctt','hlt',true,500],['set','ctt',''],['cls','ctt','hlt',false,0],['type','ctt','Our favourite fruits',70],['cap','Now everyone knows what the chart is about.']],{start:[50,60]})},
 {h:'Try a pie chart',p:`<p>A <b>pie chart</b> is a circle cut into slices, like a pizza. It's great for showing parts of a whole: which fruit got the biggest share of votes?</p><p>Click the chart, then on the <b>Chart Design</b> tab click <b>Change Chart Type</b> → <b>Pie</b>. Play with both in the practice game below!</p>`}
],
mac:['Open your Fruit survey.','Select A1 to B6 (headings and data).','Insert → Chart → Clustered Column.','Change the chart title to Our favourite fruits.','Try changing it to a Pie chart. Save your work.'],
practice:[{type:'chart'}],
challenge:'Ask your family their favourite colour, put the answers in Excel, and make a chart with a good title.',
tell:'Show your chart and say which answer won.'});

