L({id:'b25',t:'Digital art',goal:'Create digital pictures and a birthday card using drawing tools and shapes.',warm:'typing',warmLevel:4,
learn:[
 {h:'Draw with lines and shapes',p:`<p>Digital artists build pictures from simple shapes: lines, squares, triangles and circles.</p><p>Look at the house and sun: it's just a few lines and a circle! Try drawing it in the <b>Drawing studio</b> below.</p>{{||<div class="tipbox"><b>Windows bonus:</b> your computer also has <b>Paint</b>. Press <kbd>⊞ Windows</kbd>, type <b>paint</b>, press <kbd>Enter</kbd>.</div>}}`,
  demo:DEMO(drawScene,[['cap','First the ground…',300],['cls','d1','go',true,1500],['cap','A square for the house…',300],['cls','d2','go',true,1500],['cap','A triangle for the roof…',300],['cls','d3','go',true,1400],['cls','d4','go',true,1300],['cap','A circle and lines for the sun…',300],['cls','d5','go',true,1300],['cls','d6','go',true,1500],['cls','d7','go',true,1200],['cap','Simple shapes make a whole picture!']],{cls:'plain',noCursor:true})},
 {h:'Make a card with PowerPoint shapes',p:`<p>PowerPoint is great for cards and posters:</p><p>1. <b>Insert</b> → <b>Shapes</b>, choose a shape.</p><p>2. <b>Press and drag</b> on the slide to draw it.</p><p>3. Use <b>Shape Fill</b> to change its colour.</p><p>4. <b>Insert</b> → <b>Text Box</b> to add your message.</p>`,
  demo:DEMO(()=>pDesk(pptWin({tab:'Insert',tools:insertTools+`<span class="rbig" data-k="i-text"><span style="font:700 2cqw serif">A</span>Text Box</span>`,slide:' '})+`<div class="shapes-pop off" data-k="sp" data-anchor="i-shapes" style="left:20%;top:20%"><i data-k="sp-c" style="border-radius:50%"></i><i></i><i style="border-radius:.6cqw"></i><i style="transform:rotate(45deg) scale(.8)"></i></div>`),[['to','i-shapes'],['click'],['show','sp'],['cap','Choose the circle.',300],['to','sp-c'],['click'],['hide','sp'],['curs','cross'],['cap','Press and drag to draw it.',300],['move',42,40],['fn',async p=>{const s=p.q('slide');s.insertAdjacentHTML('beforeend','<i class="shapeg" data-k="bal" style="left:18%;top:10%;width:0;height:0;background:#FF6B8B"></i>');await sleep(50);p.q('bal').style.width='22%';p.q('bal').style.height='42%';p.cx+=9;p.cy+=15;p.c.style.transition='left .9s,top .9s';p.setCur();await sleep(1000);p.c.style.transition=''}],['curs','arrow'],['cap','A balloon! Add another in a new colour.',300],['fn',async p=>{p.q('slide').insertAdjacentHTML('beforeend','<i class="shapeg" data-k="bal2" style="left:40%;top:18%;width:0;height:0;background:#2A6FF0"></i>');await sleep(50);p.q('bal2').style.width='18%';p.q('bal2').style.height='34%';await sleep(900)}],['cap','Now add a Text Box with your message.',300],['to','i-text'],['click'],['fn',async p=>{p.q('slide').insertAdjacentHTML('beforeend','<div data-k="msg" style="position:absolute;right:6%;bottom:14%;font:700 3.4cqw \'Comic Sans MS\',cursive;color:#C2255C"></div>')},100],['type','msg','Happy Birthday!',80],['cap','A birthday card, made by you!']],{start:[50,60]})},
 {h:'Draw on photos',p:`{{<p>Open a photo by double-clicking it. It opens in <b>Preview</b>.</p><p>Click the <b>pen tip</b> button (Markup) in the toolbar. Now you can draw on the photo, add shapes and write words!</p>||<p>Open a photo by double-clicking it. It opens in <b>Photos</b>.</p><p>Click <b>Edit</b> (or the pen icon for <b>Draw</b>). Now you can draw on the photo and add words!</p>}}<p>Press <kbd>⌘</kbd> + <kbd>S</kbd> to keep your changes.</p>`,
  demo:DEMO(()=>desk(win('pv','Beach.jpg',`<div class="mtools" style="justify-content:flex-end"><span class="rb" data-k="mk" style="font-size:1.8cqw">✎</span></div><div class="prv"><div class="photo" style="background:radial-gradient(circle at 75% 25%,#FFE066 0 8%,transparent 9%),linear-gradient(#8fd3ff 55%,#F2D08A 55%)"></div><svg viewBox="0 0 100 60"><path data-k="scr" class="drawme" style="--len:220" d="M30 40 C35 30 45 30 48 38 C51 30 60 30 64 40 L47 52 Z" stroke="#E0463E" stroke-width="1.2" fill="none"/></svg></div>`,[16,6,64,74]),{app:'Preview',run:['finder','preview'],dock:prevDock}),[['cap','Click the {{Markup||Draw}} pen button.',300],['to','mk'],['click'],['cls','mk','on'],['cap','Now draw on the photo!',300],['cls','scr','go',true,1700],['cap','A heart on the beach photo!']],{start:[50,60]})}
],
mac:['Draw a house with a sun in the Drawing studio below.','In PowerPoint, make a birthday card with shapes and a Text Box.','Open a photo in {{Preview||Photos}} and draw on it (ask first if it\'s a family photo!).'],
practice:[{type:'draw',id:'art',title:'Drawing studio: a birthday card',intro:'Design a birthday card for someone special. Try Fill page first for a coloured background, then add circles for balloons!'}],
challenge:'Make a birthday card in PowerPoint for someone in your family, with at least 3 shapes, 2 colours and a message.',
tell:'Give your card to the person and explain how you made it.'});

L({id:'b26',t:'Screenshots',goal:'Take pictures of your screen, crop them and use them in your work.',warm:'typing',warmLevel:4,
learn:[
 {h:'Photo of the whole screen',p:`<p>A <b>screenshot</b> is a photo of your screen.</p>{{<p>Press <kbd>⇧</kbd> + <kbd>⌘</kbd> + <kbd>3</kbd>. You hear a camera sound, and a small picture appears in the corner. The screenshot is saved on your <b>Desktop</b>.</p>||<p>Press <kbd>⊞ Windows</kbd> + <kbd>PrtSc</kbd>. The screen dims for a moment. The screenshot is saved in <b>Pictures › Screenshots</b>.</p>}}`,
  demo:DEMO(()=>desk(notesWin('',[14,10,44,54])+`<div class="shot off" data-k="shot"></div>`,{run:['finder','notes'],dock:dockPlus})+deskIcon(['sf','Screenshot','pic',86,12,'off']),[['cap','Press {{⇧ + ⌘ + 3||⊞ Windows + PrtSc}}.',300],['if','mac',[['keys',['⇧','⌘','3'],900]]],['if','win',[['keys',['⊞','PrtSc'],900]]],['add','<div class="flash"></div>',300],['show','shot',1500],['cap','Click! A photo of the whole screen.',600],['hide','shot'],['show','sf',600],['cap','{{It\'s saved on your Desktop.||It\'s saved in Pictures › Screenshots.}}']],{noCursor:true})},
 {h:'Photo of just one part',p:`<p>Press {{<kbd>⇧</kbd> + <kbd>⌘</kbd> + <kbd>4</kbd>. The arrow turns into a <b>cross ＋</b>.||<kbd>⊞ Windows</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd>. The screen dims and the arrow turns into a <b>cross ＋</b>.}}</p><p>Press and <b>drag a box</b> around the part you want. Let go, and click! Only that part is saved.</p>{{<div class="tipbox"><b>Bonus:</b> <kbd>⇧</kbd> + <kbd>⌘</kbd> + <kbd>5</kbd> opens a screenshot toolbar with more choices.</div>||<div class="tipbox"><b>Good to know:</b> the picture is copied, so you can paste it straight into Word with <kbd>Ctrl</kbd> + <kbd>V</kbd>. Click the little message that pops up to edit or save it.</div>}}`,
  demo:DEMO(()=>desk(notesWin('',[14,10,44,54])+`<div class="shot off" data-k="shot" style="background:#fff"></div>`,{run:['finder','notes'],dock:dockPlus}),[['cap','Press {{⇧ + ⌘ + 4||⊞ Windows + Shift + S}}.',300],['if','mac',[['keys',['⇧','⌘','4'],800]]],['if','win',[['keys',['⊞','⇧','S'],800]]],['curs','cross'],['cap','The arrow becomes a cross.',300],['to','notesw',-18,-4],['fn',async p=>{p.rip('','press & drag');p.m.insertAdjacentHTML('beforeend',`<div class="selbox" data-k="sb" style="left:${p.cx}%;top:${p.cy}%;width:0;height:0"></div>`);await sleep(60);p.q('sb').style.width='30%';p.q('sb').style.height='30%';p.c.style.transition='left .9s,top .9s';p.cx+=30;p.cy+=30*1.6;p.setCur();await sleep(1000);p.c.style.transition=''}],['cap','Let go…',300],['rm','sb'],['add','<div class="flash"></div>',200],['curs','arrow'],['show','shot',1200],['cap','Only the part you chose is saved!']],{start:[50,60]})},
 {h:'Crop it',p:`<p><b>Crop</b> means cutting off the bits you don't want.</p>{{<p>1. Double-click the screenshot to open it in <b>Preview</b>.</p><p>2. Drag a box around the part you want to keep.</p><p>3. Press <kbd>⌘</kbd> + <kbd>K</kbd> to crop.</p>||<p>1. Double-click the screenshot to open it in <b>Photos</b>.</p><p>2. Click <b>Edit</b> → <b>Crop</b>.</p><p>3. Drag the corners in, then click <b>Save</b>.</p>}}`,
  demo:DEMO(()=>desk(win('pv','Screenshot.png',`<div class="prv"><div class="photo" data-k="ph" style="background:radial-gradient(circle at 50% 50%,#FF6B8B 0 14%,transparent 15%),radial-gradient(circle at 20% 30%,#FFE066 0 8%,transparent 9%),linear-gradient(#8fd3ff,#9A8CF1)"></div></div>`,[16,6,64,74]),{app:'Preview',run:['finder','preview'],dock:prevDock}),[['cap','Drag a box around the part to keep.',300],['to','ph',-8,-8],['fn',async p=>{p.rip('','drag');p.m.insertAdjacentHTML('beforeend',`<div class="selbox" data-k="sb" style="left:${p.cx}%;top:${p.cy}%;width:0;height:0"></div>`);await sleep(60);p.q('sb').style.width='16%';p.q('sb').style.height='25%';p.c.style.transition='left .9s,top .9s';p.cx+=16;p.cy+=25;p.setCur();await sleep(1000);p.c.style.transition=''}],['cap','{{Press ⌘ + K to crop.||Click Crop, then Save.}}',300],['if','mac',[['keys',['⌘','K'],800]]],['rm','sb'],['style','ph',{clipPath:'inset(22% 30% 22% 30% round 4px)'},900],['cap','Cropped! Only the heart is left.']],{start:[50,60]})},
 {h:'Put it in your work',p:`<p>Drag the screenshot straight into a Word document or PowerPoint slide. Or copy it (<kbd>⌘</kbd> + <kbd>C</kbd>) and paste it (<kbd>⌘</kbd> + <kbd>V</kbd>). Easy!</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl">How to open Notes</p><p data-k="pl">&nbsp;</p>`,{pos:[3,6,70,80]}))+deskIcon(['sf','Screenshot','pic',84,14]),[['cap','Drag the screenshot into Word…',300],['drag','sf','pl',{gone:true,drop:false}],['set','pl','<span class="imgin" style="display:inline-block;width:18cqw;height:11cqw;background:linear-gradient(160deg,#7CC4F7,#9A8CF1 55%,#F4A6C0)"></span>',400],['cap','…and it\'s in your document!']],{start:[50,60]})}
],
mac:['Take a screenshot of your whole screen. Find where it was saved.','Take a screenshot of just one part ({{⇧ + ⌘ + 4||⊞ Windows + Shift + S}}).','Crop it.','Put it into a Word document.','Move your screenshots into your Pictures folder.'],
practice:[{type:'quiz',title:'Screenshot shortcuts',qs:[
 {q:'Which shortcut takes a photo of the whole screen?',a:['{{⇧ + ⌘ + 3||⊞ Windows + PrtSc}}','{{⇧ + ⌘ + 4||⊞ Windows + Shift + S}}','⌘ + S'],c:0},
 {q:'Which shortcut lets you drag a box around one part?',a:['{{⇧ + ⌘ + 4||⊞ Windows + Shift + S}}','⌘ + Z','{{⌘ + tab||Alt + Tab}}'],c:0},
 {q:'Where does a full-screen screenshot go?',a:['{{The Desktop||Pictures › Screenshots}}','The {{Trash||Recycle Bin}}','The printer'],c:0},
 {q:'What does "crop" mean?',a:['Cut off the parts you don\'t want','Make it colourful','Delete it'],c:0},
 {q:'Which app crops pictures easily?',a:['{{Preview||Photos}}','Calculator','{{Mail||Outlook}}'],c:0}]}],
challenge:'Make a "How to" page in Word: take 3 screenshots showing how to open an app, crop them, and put them in order with a sentence under each.',
tell:'Take a screenshot while someone watches, and show where it went.'});

