L({id:'b27',t:'Cloud & sharing',goal:'Understand the cloud, keep backups and share your work safely.',warm:'typing',warmLevel:4,
learn:[
 {h:'What is the cloud?',p:`<p>The <b>cloud</b> isn't really in the sky! It means your files are saved on big computers on the internet, as well as on your computer.</p><ul><li>If your computer breaks, your work is still <b>safe</b>.</li><li>You can open your work on <b>other devices</b>, like a tablet or phone.</li></ul><p>{{On a Mac the cloud is called <b>iCloud Drive</b>. With Microsoft Office you can also use <b>OneDrive</b>.||On Windows the cloud is called <b>OneDrive</b>. It is already in File Explorer.}}</p>`,
  demo:DEMO(cloudScene,[['cap','Your story is saved on the computer…',1000],['cls','ar1','go',true,200],['style','fl',{left:'46%',top:'28%'},1600],['cap','…it travels up to the cloud…',1000],['cls','ar2','go',true,200],['style','fl',{left:'77%',top:'70%'},1600],['cap','…and you can open it on your tablet too!']],{cls:'plain',noCursor:true})},
 {h:'Save to {{iCloud Drive||OneDrive}}',p:`<p>In {{Finder||File Explorer}}, look in the sidebar for <b>{{iCloud Drive||OneDrive}}</b>.</p><p>Drag your <b>[name]'s Work</b> folder onto it (ask a grown-up first). Now everything inside is kept safe in the cloud.</p><p>When saving in Word, you can also choose <b>{{iCloud Drive||OneDrive}}</b> as the {{"Where"||folder}}.</p>`,
  demo:DEMO(()=>desk(win('fw','Documents',finderBody([['aw',"[name]'s Work",'folder'],['x2','Old drawing','pic']]),[12,6,70,72])),[['cap','Drag the folder onto {{iCloud Drive||OneDrive}}.',400],['drag','aw','fs-icloud-drive',{gone:true}],['to','fs-icloud-drive'],['click'],['cls','fs-documents','on',false,0],['cls','fs-icloud-drive','on'],['set','fw-title','{{iCloud Drive||OneDrive}}'],['set','fgrid',fileIcon(['aw2',"[name]'s Work",'folder']),400],['cap','Your work is in the cloud now!']],{start:[50,60]})},
 {h:'Backups: a spare copy',p:`<p>A <b>backup</b> is a spare copy of your work, kept somewhere else. If one copy gets lost, you still have the other.</p><p>{{Macs can make automatic backups with <b>Time Machine</b> and an external drive.||Windows can back up automatically with <b>Windows Backup</b> (to OneDrive) or <b>File History</b> (to an external drive).}} Ask a grown-up to set it up.</p><div class="tipbox"><b>Easy rule:</b> anything really important should live in at least <b>two places</b>.</div>`},
 {h:'Share your work',p:`<p>Want to send your story to someone? In {{Finder||File Explorer}}, <b>right-click</b> the file → <b>{{Share…||Share}}</b> and pick how to send it: {{<b>Mail</b>, <b>Messages</b>, or <b>AirDrop</b> (for Apple devices nearby).||<b>Outlook</b> email, <b>Nearby sharing</b> (for Windows computers close by), or an app.}}</p><p>Only share with people you know, and ask a grown-up first.</p>`,
  demo:DEMO(()=>desk(win('fw',"[name]'s Work",finderBody([['st','My story','pdf']]),[12,6,70,72])+menu('ctx',[['c1','Open'],['c2','{{Get Info||Properties}}'],['c3','Rename'],'-',['c-share','{{Share…||Share}}']],34,38)+`<div class="share off" data-k="sh" style="left:36%;top:52%"><div>${ic('mail','sh-mail')}{{Mail||Outlook}}</div><div><span class="ic" style="background:#34C759">${G.mail.replace('#2F7BF6','#34C759')}</span>{{Messages||WhatsApp}}</div><div><span class="ic" style="background:#1F8BF2"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3" fill="#fff"/><circle cx="12" cy="12" r="7" fill="none" stroke="#fff" stroke-width="1.8"/></svg></span>{{AirDrop||Nearby}}</div></div>`),[['to','st'],['click'],['cls','st','sel'],['rclick'],['show','ctx'],['to','c-share'],['cls','c-share','pick'],['click'],['hide','ctx'],['show','sh'],['cap','Choose how to send it.',600],['to','sh-mail'],['click'],['hide','sh'],['cap','An email opens with your story attached!']],{start:[50,60]})}
],
mac:['With a grown-up, find {{iCloud Drive||OneDrive}} in the {{Finder||File Explorer}} sidebar.','Save a copy of your story there.','Share your story PDF with someone using {{Share…||Share}}.'],
practice:[{type:'quiz',title:'Cloud quiz',qs:[
 {q:'What is the cloud?',a:['Computers on the internet that keep your files','A rainy day','A folder on the Desktop'],c:0},
 {q:'Why is saving to the cloud useful?',a:['Your work is safe even if your computer breaks','It makes the computer faster','It deletes old files'],c:0},
 {q:'What is a backup?',a:['A spare copy of your work','A way to go backwards','A kind of keyboard'],c:0},
 {q:'Who should you share files with?',a:['People you know','Anyone online','Strangers in games'],c:0},
 {q:'Where do you find {{iCloud Drive||OneDrive}}?',a:['In the {{Finder||File Explorer}} sidebar','In the {{Trash||Recycle Bin}}','In Calculator'],c:0}]}],
challenge:'Open one of your documents on another device (like a phone or tablet) from {{iCloud Drive||OneDrive}}.',
tell:'Explain what "the cloud" means in your own words.'});

L({id:'b28',t:'Fix-it detective',goal:'Solve common computer problems by yourself, and take good care of your computer.',warm:'typing',warmLevel:4,
learn:[
 {h:'When the computer is busy',p:`<p>{{See a colourful <b>spinning wheel</b> instead of the arrow?||See a <b>spinning circle</b>, or "(Not responding)" at the top of a window?}} The computer is busy thinking.</p><p><b>Wait</b> about a minute. Don't click lots of times: that makes it slower!</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl">My story</p><p>Once upon a time…</p>`)),[['to','doc'],['curs','none'],['fn',async p=>{p.m.insertAdjacentHTML('beforeend',`<div class="spin ${isWin()?'wspin':''}" data-k="sp" style="left:${p.cx-2}%;top:${p.cy-3}%"></div>`);if(isWin()){const t=p.q('word-title');if(t)t.textContent='My story (Not responding)'}},100],['cap','This means "I\'m busy".',1600],['cap','Wait patiently… count to 60.',1800],['rm','sp'],['set','word-title','My story'],['curs','arrow'],['cap','Done! The arrow is back.']],{start:[50,60]})},
 {h:'Close a frozen app',p:`<p>Still stuck after a minute? The app is <b>frozen</b>. Force it to close:</p>{{<p>1. Press <kbd>⌥ option</kbd> + <kbd>⌘</kbd> + <kbd>esc</kbd>.</p><p>2. Click the frozen app in the list.</p><p>3. Click <b>Force Quit</b>.</p>||<p>1. Press <kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>Esc</kbd> to open <b>Task Manager</b>.</p><p>2. Click the frozen app in the list.</p><p>3. Click <b>End task</b>.</p>}}<p>Then open the app again. (Anything you didn't save may be lost, so save often!)</p>`,
  demo:DEMO(()=>wDesk(wordWin(`<p class="ttl">My story</p>`))+`<div class="fq off" data-k="fq"><div class="fqh">{{Force Quit Applications||Task Manager}}</div><div class="fql"><div>${ic('finder')} {{Finder||File Explorer}}</div><div data-k="fq-w">${ic('word')} Microsoft Word (not responding)</div><div>${ic('safari')} {{Safari||Microsoft Edge}}</div></div><div class="row"><span class="b2 pri" data-k="fq-go">{{Force Quit||End task}}</span></div></div>`,[['cap','Press {{⌥ + ⌘ + esc||Ctrl + Shift + Esc}}.',300],['if','mac',[['keys',['⌥','⌘','esc'],1000]]],['if','win',[['keys',['Ctrl','⇧','esc'],1000]]],['show','fq',500],['cap','Click the frozen app.',300],['to','fq-w'],['click'],['cls','fq-w','pick'],['cap','Click <b>{{Force Quit||End task}}</b>.',300],['to','fq-go'],['click'],['hide','fq'],['hide','word',500],['cls','d-word','run',false],['cap','Closed! Now open it again.']],{start:[50,60]})},
 {h:'No sound? No internet?',p:`<p><b>No sound?</b> Turn the volume up. Check mute is off. Are headphones plugged in? Unplug them.</p><p><b>No internet?</b> Open {{Control Centre||Quick Settings}}. Is Wi-Fi grey? Click it to turn it on (blue). Still nothing? Turn Wi-Fi off, wait 10 seconds, turn it on. Then ask someone to check the router.</p>`,
  demo:DEMO(()=>desk(ccPanel()),[['cap','No internet? Open {{Control Centre||Quick Settings}}.',300],['fn',async p=>{p.q('cc-wdot').classList.add('no');p.q('cc-wname').textContent='Off';p.q('cc-vol').style.width='0%'},0],['to','cc'],['click'],['show','ccp',600],['cap','Wi-Fi is grey (off). Click it!',300],['to','cc-wdot'],['click'],['cls','cc-wdot','no',false],['set','cc-wname','HomeWiFi',900],['cap','Blue again: connected! Sound is at 0…',400],['to','cc-vol',-6],['style','cc-vol',{width:'60%'}],['to','cc-vol',6,0,900],['cap','Volume up. Problem solved, detective!']],{start:[50,55]})},
 {h:'Restart and computer care',p:`<p><b>Magic fix:</b> many problems disappear after a restart. {{Apple menu → <b>Restart…</b>||Start → Power → <b>Restart</b>}}</p><p><b>Look after your computer:</b></p><ul><li>Clean, dry hands. No food or drinks near it.</li><li>Close the lid gently, with nothing on the keyboard.</li><li>Charge it before the battery is empty.</li><li>Carry it with two hands, closed.</li><li>Install updates when the computer asks (ask a grown-up).</li></ul>`,
  demo:DEMO(()=>desk(appleMenu()+dlg('rs','Are you sure you want to restart your computer now?','',[['rs-c','Cancel'],['rs-ok','Restart','pri']])+blackLayer(true)),[...startOpen(),...startPick('am-restart'),['if','mac',[['show','rs'],['to','rs-ok'],['click'],['hide','rs']]],['show','black',1400],['cap','Restarting…',1000],['hide','black',1000],['cap','Fresh and ready! Restarting fixes lots of problems.']],{start:[40,50]})}
],
mac:['Practise on Calculator: open it, then close it with {{⌥ + ⌘ + esc → Force Quit||Ctrl + Shift + Esc → End task}}.','Turn Wi-Fi off and on again.','Mute and unmute the sound.','Restart your computer.','Wipe your screen gently with a soft dry cloth.'],
practice:[{type:'quiz',title:'Detective cases',qs:[
 {q:'Case 1: The computer looks busy (spinning). What do you do first?',a:['Wait about a minute','Click 50 times','Pull out the charger'],c:0},
 {q:'Case 2: Word is frozen for a long time. What do you press?',a:['{{⌥ + ⌘ + esc||Ctrl + Shift + Esc}}','⌘ + C','⌘ + S'],c:0,why:'Then choose Word and click {{Force Quit||End task}}.'},
 {q:'Case 3: No sound from the videos. What could be wrong?',a:['Mute is on or the volume is at 0','The screen is too bright','The {{Trash||Recycle Bin}} is full'],c:0},
 {q:'Case 4: Websites won\'t load and Wi-Fi is grey.',a:['Turn Wi-Fi on','Buy a new computer','Delete the browser'],c:0},
 {q:'Case 5: Everything feels slow and strange.',a:['Save your work and restart','Shake the computer','Pour water on it'],c:0},
 {q:'Case 6: You want a drink while working.',a:['Keep it far away from the computer','Put it next to the keyboard','Drink over the keyboard'],c:0}]}],
challenge:'Write a "Fix-it guide" in Word with 5 problems and how to solve each one. Add a screenshot to one of them.',
tell:'Show how to close a frozen app, and explain when to use it.'});

/* ============================== UNIT 5: Graduation ============================== */
L({id:'b29',t:'The Expert Project',goal:'Use Word, Excel and PowerPoint together to make one amazing project.',warm:'typing',warmLevel:4,
learn:[
 {h:'Pick your topic',p:`<p>Choose something you love. Some ideas:</p><div class="recap"><div><b>Dubai landmarks</b>Burj Khalifa, Dubai Frame, Museum of the Future</div><div><b>UAE animals</b>Arabian oryx, falcon, camel, dugong</div><div><b>Space</b>The planets, or the UAE's Mars mission</div><div><b>My hobby</b>Drawing, football, baking, reading</div></div>`},
 {h:'Research safely',p:`<ul><li>Search with good keywords on a safe search.</li><li>Find <b>5 facts</b>. Check each one on two websites.</li><li>Take <b>screenshots</b> of 2 or 3 pictures and save them in your <b>Pictures</b> folder.</li><li>Write down the websites you used.</li></ul>`},
 {h:'Build the three parts',p:`<div class="recap"><div><b>Word</b>A one-page report: bold centred title, 3 paragraphs, 1 picture, spell-checked.</div><div><b>Excel</b>A small table of numbers about your topic (heights, speeds, ages…) with a SUM and a chart.</div><div><b>PowerPoint</b>5 or 6 slides: title, facts, your Excel chart (copy and paste it in!), pictures, "Thank you".</div></div><div class="tipbox" style="margin-top:12px"><b>Stay organised:</b> make a folder called <b>Expert Project</b> inside [name]'s Work and save all three files there.</div>`}
],
mac:['Make a folder called Expert Project in [name]\'s Work.','Research 5 facts and save 2–3 pictures.','Word: write your one-page report and save it.','Excel: make a table, a SUM and a chart.','PowerPoint: make 5–6 slides and paste in your chart.','Save everything, and save a PDF copy of your report.'],
practice:[],
challenge:'Finish all three parts of your project. Next lesson is Presentation Day!',
tell:'Tell your family your topic and one surprising fact you found.'});

L({id:'b30',t:'Basic Graduation',goal:'Present your project, take the final quiz and typing test, and get your certificate!',warm:'typing',warmLevel:4,final:'basic',
learn:[
 {h:'Presentation Day',p:`<p>Invite your family to watch. Start your slide show with <b>From Beginning</b> and present your Expert Project.</p><ul><li>Stand tall, smile, speak slowly.</li><li>Show your Word report and Excel chart too.</li><li>End with "Any questions?"</li></ul>`},
 {h:'Final quiz and typing test',p:`<p>Below are the <b>final quiz</b> and the <b>typing speed test</b>. Take your time and do your best. Then press <b>Show my certificate</b>. You earned it!</p>`},
 {h:'What next?',p:`<p>You're ready for the <b>Advanced course</b>: power-user tricks, pro Word and Excel skills, teamwork in the cloud, online security, and creative and coding projects. Ask your admin to switch you to the Advanced course, or choose it on your profile page.</p>`}
],
mac:['Present your Expert Project to your family.','Take the final quiz below.','Do the typing speed test.','Get your certificate and take a screenshot of it.','Celebrate!'],
practice:[{type:'quiz',id:'basic-final',title:'Final quiz',shuffle:true,take:15,qs:[
 {q:'How do you shut down properly?',a:['{{Apple menu → Shut Down…||Start → Power → Shut down}}','Pull out the charger','Close the lid'],c:0},
 {q:'How do you right-click on a {{trackpad||touchpad}}?',a:['{{Click with two fingers||Tap with two fingers}}','Click with one finger very hard','Press {{esc||Esc}}'],c:0},
 {q:'Where do your pointer fingers rest on the home row?',a:['F and J','A and ;','G and H'],c:0},
 {q:'Which window button makes it fill the screen?',a:['{{Green||☐ Maximise}}','{{Red||✕}}','{{Yellow||─}}'],c:0},
 {q:'How do you search for an app quickly?',a:['{{⌘ + space||⊞ Windows key, then type}}','⌘ + S','⌘ + P'],c:0},
 {q:'What is the shortcut to paste?',a:['⌘ + V','⌘ + P','⌘ + C'],c:0},
 {q:'How do you rescue a file you deleted?',a:['{{Trash → right-click → Put Back||Recycle Bin → right-click → Restore}}','Empty the {{Trash||Recycle Bin}}','Restart'],c:0},
 {q:'Which shortcut locks the screen?',a:['{{⌃ + ⌘ + Q||⊞ Windows + L}}','⌘ + L','⌘ + T'],c:0},
 {q:'A pop-up says "You won a prize". What do you do?',a:['Close it and tell someone','Click to claim it','Type your address'],c:0},
 {q:'Every email address has which symbol?',a:['@','#','&'],c:0},
 {q:'What does ⌘ + B do in Word?',a:['Makes words bold','Opens the browser','Adds a bullet'],c:0},
 {q:'Which key goes to the next slide in a slide show?',a:['→','⌘','{{esc||Esc}}'],c:0},
 {q:'What does =SUM(B2:B6) do?',a:['Adds B2 to B6','Deletes B2 to B6','Makes B2 bold'],c:0},
 {q:'Which shortcut takes a screenshot of part of the screen?',a:['{{⇧ + ⌘ + 4||⊞ Windows + Shift + S}}','⌘ + K','⌘ + Z'],c:0},
 {q:'An app is frozen. What do you press?',a:['{{⌥ + ⌘ + esc||Ctrl + Shift + Esc}}','⌘ + C','⌘ + N'],c:0},
 {q:'What is the cloud?',a:['Computers on the internet that store your files','Fog on the screen','A drawing tool'],c:0},
 {q:'Which cell is in column C, row 4?',a:['C4','4C','D3'],c:0},
 {q:'Words flying in on one slide is…',a:['an animation','a transition','a table'],c:0}]},{type:'typing',test:true,title:'Typing speed test'},{type:'cert',track:'Basic',label:'Computer Explorer'}],
challenge:'Present your Expert Project to at least 2 people, and answer their questions.',
tell:'Show your certificate and tell everyone your favourite thing you learned!'});
